class UserSession extends DataClass implements Insertable<UserSession> {
  /// The session's own identifier (UUID). Distinct from the token: this is
  /// safe to log and to show in a "signed-in devices" list.
  final String id;
  final int userId;

  /// Lower-case hex SHA-256 of the bearer token.
  final String tokenHash;

  /// What the user sees in the device list, e.g. "Counter 2" or "Nimal's
  /// phone". Supplied by the client at sign-in; never trusted for anything
  /// but display.
  final String? deviceLabel;

  /// `windows`, `android`, or whatever a later client reports. Recorded for
  /// the device list and for support, not used in any decision.
  final String? deviceKind;
  final DateTime createdAt;

  /// Updated on use, which is what the idle timeout is measured from.
  final DateTime lastSeenAt;

  /// Hard expiry, independent of activity.
  final DateTime expiresAt;

  /// Set when the session is ended deliberately — sign-out, an administrator
  /// revoking a device, or a password change. A revoked row is kept rather
  /// than deleted so the audit trail still explains why access stopped.
  final DateTime? revokedAt;
  final String? revokedReason;
  const UserSession({
    required this.id,
    required this.userId,
    required this.tokenHash,
    this.deviceLabel,
    this.deviceKind,
    required this.createdAt,
    required this.lastSeenAt,
    required this.expiresAt,
    this.revokedAt,
    this.revokedReason,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['user_id'] = Variable<int>(userId);
    map['token_hash'] = Variable<String>(tokenHash);
    if (!nullToAbsent || deviceLabel != null) {
      map['device_label'] = Variable<String>(deviceLabel);
    }
    if (!nullToAbsent || deviceKind != null) {
      map['device_kind'] = Variable<String>(deviceKind);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['last_seen_at'] = Variable<DateTime>(lastSeenAt);
    map['expires_at'] = Variable<DateTime>(expiresAt);
    if (!nullToAbsent || revokedAt != null) {
      map['revoked_at'] = Variable<DateTime>(revokedAt);
    }
    if (!nullToAbsent || revokedReason != null) {
      map['revoked_reason'] = Variable<String>(revokedReason);
    }
    return map;
  }

  UserSessionsCompanion toCompanion(bool nullToAbsent) {
    return UserSessionsCompanion(
      id: Value(id),
      userId: Value(userId),
      tokenHash: Value(tokenHash),
      deviceLabel: deviceLabel == null && nullToAbsent
          ? const Value.absent()
          : Value(deviceLabel),
      deviceKind: deviceKind == null && nullToAbsent
          ? const Value.absent()
          : Value(deviceKind),
      createdAt: Value(createdAt),
      lastSeenAt: Value(lastSeenAt),
      expiresAt: Value(expiresAt),
      revokedAt: revokedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(revokedAt),
      revokedReason: revokedReason == null && nullToAbsent
