class Agent extends DataClass implements Insertable<Agent> {
  final int id;
  final String code;
  final String name;
  final String? phone;
  final String? address;
  final String? nic;

  /// Commission rate in basis points (1000 = 10%). Optional.
  final int? commissionBps;

  /// Receivable carried over from before the system went live. Positive means
  /// the agent owes the business.
  final int openingBalanceCents;
  final EntityStatus status;
  final String? notes;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Agent({
    required this.id,
    required this.code,
    required this.name,
    this.phone,
    this.address,
    this.nic,
    this.commissionBps,
    required this.openingBalanceCents,
    required this.status,
    this.notes,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['code'] = Variable<String>(code);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || phone != null) {
      map['phone'] = Variable<String>(phone);
    }
    if (!nullToAbsent || address != null) {
      map['address'] = Variable<String>(address);
    }
    if (!nullToAbsent || nic != null) {
      map['nic'] = Variable<String>(nic);
    }
    if (!nullToAbsent || commissionBps != null) {
      map['commission_bps'] = Variable<int>(commissionBps);
    }
    map['opening_balance_cents'] = Variable<int>(openingBalanceCents);
    {
      map['status'] = Variable<String>(
        $AgentsTable.$converterstatus.toSql(status),
      );
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  AgentsCompanion toCompanion(bool nullToAbsent) {
    return AgentsCompanion(
      id: Value(id),
      code: Value(code),
      name: Value(name),
      phone: phone == null && nullToAbsent
          ? const Value.absent()
          : Value(phone),
      address: address == null && nullToAbsent
          ? const Value.absent()
          : Value(address),
      nic: nic == null && nullToAbsent ? const Value.absent() : Value(nic),
      commissionBps: commissionBps == null && nullToAbsent
          ? const Value.absent()
          : Value(commissionBps),
      openingBalanceCents: Value(openingBalanceCents),
      status: Value(status),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Agent.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Agent(
      id: serializer.fromJson<int>(json['id']),
      code: serializer.fromJson<String>(json['code']),
      name: serializer.fromJson<String>(json['name']),
      phone: serializer.fromJson<String?>(json['phone']),
      address: serializer.fromJson<String?>(json['address']),
      nic: serializer.fromJson<String?>(json['nic']),
      commissionBps: serializer.fromJson<int?>(json['commissionBps']),
      openingBalanceCents: serializer.fromJson<int>(
        json['openingBalanceCents'],
      ),
      status: $AgentsTable.$converterstatus.fromJson(
        serializer.fromJson<String>(json['status']),
      ),
      notes: serializer.fromJson<String?>(json['notes']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'code': serializer.toJson<String>(code),
      'name': serializer.toJson<String>(name),
      'phone': serializer.toJson<String?>(phone),
      'address': serializer.toJson<String?>(address),
      'nic': serializer.toJson<String?>(nic),
      'commissionBps': serializer.toJson<int?>(commissionBps),
      'openingBalanceCents': serializer.toJson<int>(openingBalanceCents),
      'status': serializer.toJson<String>(
        $AgentsTable.$converterstatus.toJson(status),
      ),
      'notes': serializer.toJson<String?>(notes),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

  Agent copyWith({
    int? id,
    String? code,
    String? name,
    Value<String?> phone = const Value.absent(),
    Value<String?> address = const Value.absent(),
    Value<String?> nic = const Value.absent(),
    Value<int?> commissionBps = const Value.absent(),
    int? openingBalanceCents,
    EntityStatus? status,
    Value<String?> notes = const Value.absent(),
    DateTime? createdAt,
    DateTime? updatedAt,
  }) => Agent(
    id: id ?? this.id,
    code: code ?? this.code,
    name: name ?? this.name,
    phone: phone.present ? phone.value : this.phone,
    address: address.present ? address.value : this.address,
    nic: nic.present ? nic.value : this.nic,
    commissionBps: commissionBps.present
        ? commissionBps.value
        : this.commissionBps,
    openingBalanceCents: openingBalanceCents ?? this.openingBalanceCents,
    status: status ?? this.status,
    notes: notes.present ? notes.value : this.notes,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
  );
  Agent copyWithCompanion(AgentsCompanion data) {
    return Agent(
      id: data.id.present ? data.id.value : this.id,
      code: data.code.present ? data.code.value : this.code,
      name: data.name.present ? data.name.value : this.name,
      phone: data.phone.present ? data.phone.value : this.phone,
      address: data.address.present ? data.address.value : this.address,
      nic: data.nic.present ? data.nic.value : this.nic,
      commissionBps: data.commissionBps.present
          ? data.commissionBps.value
          : this.commissionBps,
      openingBalanceCents: data.openingBalanceCents.present
          ? data.openingBalanceCents.value
          : this.openingBalanceCents,
      status: data.status.present ? data.status.value : this.status,
      notes: data.notes.present ? data.notes.value : this.notes,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Agent(')
          ..write('id: $id, ')
          ..write('code: $code, ')
          ..write('name: $name, ')
          ..write('phone: $phone, ')
          ..write('address: $address, ')
          ..write('nic: $nic, ')
          ..write('commissionBps: $commissionBps, ')
          ..write('openingBalanceCents: $openingBalanceCents, ')
          ..write('status: $status, ')
          ..write('notes: $notes, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode => Object.hash(
    id,
    code,
    name,
    phone,
    address,
    nic,
    commissionBps,
    openingBalanceCents,
    status,
    notes,
    createdAt,
    updatedAt,
  );
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Agent &&
          other.id == this.id &&
          other.code == this.code &&
          other.name == this.name &&
          other.phone == this.phone &&
          other.address == this.address &&
          other.nic == this.nic &&
          other.commissionBps == this.commissionBps &&
          other.openingBalanceCents == this.openingBalanceCents &&
          other.status == this.status &&
          other.notes == this.notes &&
          other.createdAt == this.createdAt &&
          other.updatedAt == this.updatedAt);
}

