          ..write('phone: $phone, ')
          ..write('address: $address, ')
          ..write('assignedAgentId: $assignedAgentId, ')
          ..write('openingBalanceCents: $openingBalanceCents, ')
          ..write('creditLimitCents: $creditLimitCents, ')
          ..write('status: $status, ')
          ..write('notes: $notes, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }

