class Product extends DataClass implements Insertable<Product> {
  final int id;

  /// Human-facing stock keeping unit, unique across the catalogue.
  final String sku;
  final String name;

  /// Optional scanned barcode. Unique when present.
  final String? barcode;
  final int categoryId;
  final String? brand;
  final String? description;

  /// Unit the product is counted in for display purposes. Stock is always
  /// stored in base units.
  final UnitOfMeasure unitOfMeasure;

  /// Base units contained in one pack/box, used to convert pack entry into
  /// base units at data-entry time. Always >= 1.
  final int unitsPerPack;

  /// Current purchase cost, used as the default valuation cost for new
  /// movements. Historical cost is snapshotted on each ledger entry.
  final int costPriceCents;

  /// Default price charged to agents and shops.
  final int wholesalePriceCents;

  /// Default price a shop charges an end customer.
  final int retailPriceCents;

  /// Quantity at or below which the product is reported as low stock.
  final int reorderLevel;
  final EntityStatus status;
  final String? notes;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Product({
    required this.id,
    required this.sku,
    required this.name,
    this.barcode,
    required this.categoryId,
    this.brand,
    this.description,
    required this.unitOfMeasure,
    required this.unitsPerPack,
    required this.costPriceCents,
    required this.wholesalePriceCents,
    required this.retailPriceCents,
    required this.reorderLevel,
    required this.status,
    this.notes,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['sku'] = Variable<String>(sku);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || barcode != null) {
      map['barcode'] = Variable<String>(barcode);
    }
    map['category_id'] = Variable<int>(categoryId);
    if (!nullToAbsent || brand != null) {
      map['brand'] = Variable<String>(brand);
    }
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    {
      map['unit_of_measure'] = Variable<String>(
        $ProductsTable.$converterunitOfMeasure.toSql(unitOfMeasure),
      );
    }
    map['units_per_pack'] = Variable<int>(unitsPerPack);
    map['cost_price_cents'] = Variable<int>(costPriceCents);
    map['wholesale_price_cents'] = Variable<int>(wholesalePriceCents);
    map['retail_price_cents'] = Variable<int>(retailPriceCents);
    map['reorder_level'] = Variable<int>(reorderLevel);
    {
      map['status'] = Variable<String>(
        $ProductsTable.$converterstatus.toSql(status),
      );
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  ProductsCompanion toCompanion(bool nullToAbsent) {
    return ProductsCompanion(
      id: Value(id),
      sku: Value(sku),
      name: Value(name),
      barcode: barcode == null && nullToAbsent
          ? const Value.absent()
          : Value(barcode),
      categoryId: Value(categoryId),
      brand: brand == null && nullToAbsent
          ? const Value.absent()
          : Value(brand),
      description: description == null && nullToAbsent
          ? const Value.absent()
          : Value(description),
      unitOfMeasure: Value(unitOfMeasure),
      unitsPerPack: Value(unitsPerPack),
      costPriceCents: Value(costPriceCents),
      wholesalePriceCents: Value(wholesalePriceCents),
      retailPriceCents: Value(retailPriceCents),
      reorderLevel: Value(reorderLevel),
      status: Value(status),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

  factory Product.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Product(
      id: serializer.fromJson<int>(json['id']),
      sku: serializer.fromJson<String>(json['sku']),
      name: serializer.fromJson<String>(json['name']),
      barcode: serializer.fromJson<String?>(json['barcode']),
      categoryId: serializer.fromJson<int>(json['categoryId']),
      brand: serializer.fromJson<String?>(json['brand']),
      description: serializer.fromJson<String?>(json['description']),
      unitOfMeasure: $ProductsTable.$converterunitOfMeasure.fromJson(
        serializer.fromJson<String>(json['unitOfMeasure']),
      ),
      unitsPerPack: serializer.fromJson<int>(json['unitsPerPack']),
      costPriceCents: serializer.fromJson<int>(json['costPriceCents']),
      wholesalePriceCents: serializer.fromJson<int>(
        json['wholesalePriceCents'],
      ),
      retailPriceCents: serializer.fromJson<int>(json['retailPriceCents']),
      reorderLevel: serializer.fromJson<int>(json['reorderLevel']),
      status: $ProductsTable.$converterstatus.fromJson(
        serializer.fromJson<String>(json['status']),
      ),
      notes: serializer.fromJson<String?>(json['notes']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'sku': serializer.toJson<String>(sku),
      'name': serializer.toJson<String>(name),
      'barcode': serializer.toJson<String?>(barcode),
      'categoryId': serializer.toJson<int>(categoryId),
      'brand': serializer.toJson<String?>(brand),
      'description': serializer.toJson<String?>(description),
      'unitOfMeasure': serializer.toJson<String>(
        $ProductsTable.$converterunitOfMeasure.toJson(unitOfMeasure),
      ),
      'unitsPerPack': serializer.toJson<int>(unitsPerPack),
      'costPriceCents': serializer.toJson<int>(costPriceCents),
      'wholesalePriceCents': serializer.toJson<int>(wholesalePriceCents),
      'retailPriceCents': serializer.toJson<int>(retailPriceCents),
      'reorderLevel': serializer.toJson<int>(reorderLevel),
      'status': serializer.toJson<String>(
        $ProductsTable.$converterstatus.toJson(status),
      ),
      'notes': serializer.toJson<String?>(notes),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

  Product copyWith({
    int? id,
    String? sku,
    String? name,
    Value<String?> barcode = const Value.absent(),
    int? categoryId,
    Value<String?> brand = const Value.absent(),
    Value<String?> description = const Value.absent(),
    UnitOfMeasure? unitOfMeasure,
    int? unitsPerPack,
    int? costPriceCents,
    int? wholesalePriceCents,
    int? retailPriceCents,
    int? reorderLevel,
    EntityStatus? status,
    Value<String?> notes = const Value.absent(),
    DateTime? createdAt,
    DateTime? updatedAt,
  }) => Product(
    id: id ?? this.id,
    sku: sku ?? this.sku,
    name: name ?? this.name,
    barcode: barcode.present ? barcode.value : this.barcode,
    categoryId: categoryId ?? this.categoryId,
    brand: brand.present ? brand.value : this.brand,
    description: description.present ? description.value : this.description,
    unitOfMeasure: unitOfMeasure ?? this.unitOfMeasure,
    unitsPerPack: unitsPerPack ?? this.unitsPerPack,
    costPriceCents: costPriceCents ?? this.costPriceCents,
    wholesalePriceCents: wholesalePriceCents ?? this.wholesalePriceCents,
    retailPriceCents: retailPriceCents ?? this.retailPriceCents,
    reorderLevel: reorderLevel ?? this.reorderLevel,
    status: status ?? this.status,
    notes: notes.present ? notes.value : this.notes,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
  );
  Product copyWithCompanion(ProductsCompanion data) {
    return Product(
      id: data.id.present ? data.id.value : this.id,
      sku: data.sku.present ? data.sku.value : this.sku,
      name: data.name.present ? data.name.value : this.name,
      barcode: data.barcode.present ? data.barcode.value : this.barcode,
      categoryId: data.categoryId.present
          ? data.categoryId.value
          : this.categoryId,
      brand: data.brand.present ? data.brand.value : this.brand,
      description: data.description.present
          ? data.description.value
          : this.description,
      unitOfMeasure: data.unitOfMeasure.present
          ? data.unitOfMeasure.value
          : this.unitOfMeasure,
      unitsPerPack: data.unitsPerPack.present
          ? data.unitsPerPack.value
          : this.unitsPerPack,
      costPriceCents: data.costPriceCents.present
          ? data.costPriceCents.value
          : this.costPriceCents,
      wholesalePriceCents: data.wholesalePriceCents.present
          ? data.wholesalePriceCents.value
          : this.wholesalePriceCents,
      retailPriceCents: data.retailPriceCents.present
          ? data.retailPriceCents.value
          : this.retailPriceCents,
      reorderLevel: data.reorderLevel.present
          ? data.reorderLevel.value
          : this.reorderLevel,
      status: data.status.present ? data.status.value : this.status,
      notes: data.notes.present ? data.notes.value : this.notes,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Product(')
          ..write('id: $id, ')
          ..write('sku: $sku, ')
          ..write('name: $name, ')
          ..write('barcode: $barcode, ')
