class InventoryLocation extends DataClass
    implements Insertable<InventoryLocation> {
  final int id;
  final String code;
  final String name;
  final LocationKind kind;

  /// Set when [kind] is [LocationKind.agent].
  final int? agentId;

  /// Set when [kind] is [LocationKind.shop].
  final int? shopId;
  final bool isActive;
  final DateTime createdAt;
  const InventoryLocation({
    required this.id,
    required this.code,
    required this.name,
    required this.kind,
    this.agentId,
    this.shopId,
    required this.isActive,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['code'] = Variable<String>(code);
    map['name'] = Variable<String>(name);
    {
      map['kind'] = Variable<String>(
        $InventoryLocationsTable.$converterkind.toSql(kind),
      );
    }
    if (!nullToAbsent || agentId != null) {
      map['agent_id'] = Variable<int>(agentId);
    }
    if (!nullToAbsent || shopId != null) {
      map['shop_id'] = Variable<int>(shopId);
    }
    map['is_active'] = Variable<bool>(isActive);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  InventoryLocationsCompanion toCompanion(bool nullToAbsent) {
    return InventoryLocationsCompanion(
      id: Value(id),
      code: Value(code),
      name: Value(name),
      kind: Value(kind),
      agentId: agentId == null && nullToAbsent
          ? const Value.absent()
          : Value(agentId),
      shopId: shopId == null && nullToAbsent
          ? const Value.absent()
          : Value(shopId),
      isActive: Value(isActive),
      createdAt: Value(createdAt),
    );
  }

  factory InventoryLocation.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return InventoryLocation(
      id: serializer.fromJson<int>(json['id']),
      code: serializer.fromJson<String>(json['code']),
      name: serializer.fromJson<String>(json['name']),
      kind: $InventoryLocationsTable.$converterkind.fromJson(
        serializer.fromJson<String>(json['kind']),
      ),
      agentId: serializer.fromJson<int?>(json['agentId']),
      shopId: serializer.fromJson<int?>(json['shopId']),
      isActive: serializer.fromJson<bool>(json['isActive']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'code': serializer.toJson<String>(code),
      'name': serializer.toJson<String>(name),
      'kind': serializer.toJson<String>(
        $InventoryLocationsTable.$converterkind.toJson(kind),
      ),
      'agentId': serializer.toJson<int?>(agentId),
      'shopId': serializer.toJson<int?>(shopId),
      'isActive': serializer.toJson<bool>(isActive),
      'createdAt': serializer.toJson<DateTime>(createdAt),
    };
  }

  InventoryLocation copyWith({
    int? id,
    String? code,
    String? name,
    LocationKind? kind,
    Value<int?> agentId = const Value.absent(),
    Value<int?> shopId = const Value.absent(),
    bool? isActive,
    DateTime? createdAt,
  }) => InventoryLocation(
    id: id ?? this.id,
    code: code ?? this.code,
    name: name ?? this.name,
    kind: kind ?? this.kind,
    agentId: agentId.present ? agentId.value : this.agentId,
    shopId: shopId.present ? shopId.value : this.shopId,
    isActive: isActive ?? this.isActive,
    createdAt: createdAt ?? this.createdAt,
  );
  InventoryLocation copyWithCompanion(InventoryLocationsCompanion data) {
    return InventoryLocation(
      id: data.id.present ? data.id.value : this.id,
      code: data.code.present ? data.code.value : this.code,
      name: data.name.present ? data.name.value : this.name,
      kind: data.kind.present ? data.kind.value : this.kind,
      agentId: data.agentId.present ? data.agentId.value : this.agentId,
      shopId: data.shopId.present ? data.shopId.value : this.shopId,
      isActive: data.isActive.present ? data.isActive.value : this.isActive,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
    );
  }

  @override
  String toString() {
    return (StringBuffer('InventoryLocation(')
          ..write('id: $id, ')
          ..write('code: $code, ')
          ..write('name: $name, ')
          ..write('kind: $kind, ')
          ..write('agentId: $agentId, ')
          ..write('shopId: $shopId, ')
          ..write('isActive: $isActive, ')
          ..write('createdAt: $createdAt')
          ..write(')'))
        .toString();
  }

  @override
