    this.shopId,
    required this.totalQuantity,
    required this.subtotalCents,
    required this.discountTotalCents,
    required this.totalCents,
    required this.negativeStockOverride,
    this.overrideApprovedByUserId,
    this.overrideReason,
    this.reversesTransactionId,
    this.referenceNote,
    this.notes,
    required this.createdByUserId,
    required this.createdAt,
    this.postedAt,
    this.postedByUserId,
    this.cancelledAt,
    this.cancelledByUserId,
    this.cancelReason,
  });
