      map['shop_id'] = Variable<int>(shopId);
    }
    map['total_quantity'] = Variable<int>(totalQuantity);
    map['subtotal_cents'] = Variable<int>(subtotalCents);
    map['discount_total_cents'] = Variable<int>(discountTotalCents);
    map['total_cents'] = Variable<int>(totalCents);
    map['negative_stock_override'] = Variable<bool>(negativeStockOverride);
    if (!nullToAbsent || overrideApprovedByUserId != null) {
