    {
      map['discount_type'] = Variable<String>(
        $StockTransactionItemsTable.$converterdiscountType.toSql(discountType),
      );
    }
    map['discount_value'] = Variable<int>(discountValue);
    map['discount_cents'] = Variable<int>(discountCents);
    map['line_total_cents'] = Variable<int>(lineTotalCents);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    return map;
