      map['transaction_item_id'] = Variable<int>(transactionItemId);
    }
    map['location_id'] = Variable<int>(locationId);
    map['product_id'] = Variable<int>(productId);
    map['quantity_delta'] = Variable<int>(quantityDelta);
    map['balance_after'] = Variable<int>(balanceAfter);
    map['unit_cost_cents'] = Variable<int>(unitCostCents);
    {
      map['entry_type'] = Variable<String>(
        $StockLedgerEntriesTable.$converterentryType.toSql(entryType),
      );
    }
    map['occurred_at'] = Variable<DateTime>(occurredAt);
    map['recorded_at'] = Variable<DateTime>(recordedAt);
    map['recorded_by_user_id'] = Variable<int>(recordedByUserId);
    if (!nullToAbsent || narration != null) {
      map['narration'] = Variable<String>(narration);
    }
    return map;
  }

  StockLedgerEntriesCompanion toCompanion(bool nullToAbsent) {
    return StockLedgerEntriesCompanion(
      id: Value(id),
      transactionId: Value(transactionId),
      transactionItemId: transactionItemId == null && nullToAbsent
