class StockBalance extends DataClass implements Insertable<StockBalance> {
  final int id;
  final int locationId;
  final int productId;
  final int quantity;

  /// Weighted average cost per base unit held at this location, maintained on
  /// inbound movements and used for stock valuation reports.
  final int averageCostCents;
  final DateTime updatedAt;
  const StockBalance({
    required this.id,
    required this.locationId,
    required this.productId,
    required this.quantity,
    required this.averageCostCents,
    required this.updatedAt,
