    averageCostCents: averageCostCents ?? this.averageCostCents,
    updatedAt: updatedAt ?? this.updatedAt,
  );
  StockBalance copyWithCompanion(StockBalancesCompanion data) {
    return StockBalance(
      id: data.id.present ? data.id.value : this.id,
      locationId: data.locationId.present
          ? data.locationId.value
          : this.locationId,
      productId: data.productId.present ? data.productId.value : this.productId,
      quantity: data.quantity.present ? data.quantity.value : this.quantity,
      averageCostCents: data.averageCostCents.present
          ? data.averageCostCents.value
          : this.averageCostCents,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
    );
