  static JsonTypeConverter2<PartyType, String, String> $converterpartyType =
      const EnumNameConverter<PartyType>(PartyType.values);
  static JsonTypeConverter2<DiscountType, String, String>
  $converterinvoiceDiscountType = const EnumNameConverter<DiscountType>(
    DiscountType.values,
  );
}

class Invoice extends DataClass implements Insertable<Invoice> {
  final int id;

  /// Unique across every kind of invoice, e.g. `SINV-2026-00231`.
  final String invoiceNumber;
  final InvoiceKind kind;
  final InvoiceStatus status;
  final DateTime invoiceDate;
  final DateTime? dueDate;
  final PartyType partyType;

  /// The agent being billed, or the agent responsible for a shop invoice.
  final int? agentId;
  final int? shopId;

  /// Walk-in customer details for a retail sale. Retail sales are deliberately
  /// not forced to create a party record.
  final String? customerName;
  final String? customerPhone;

  /// The goods movement this invoice bills for, when there is one.
  final int? stockTransactionId;

  /// Sum of line gross amounts before any discount.
  final int grossTotalCents;

  /// Sum of the per-line discounts.
  final int itemDiscountTotalCents;
  final DiscountType invoiceDiscountType;

  /// Basis points when the type is percentage, cents when fixed amount.
  final int invoiceDiscountValue;

  /// Resolved cash value of the invoice-level discount.
  final int invoiceDiscountCents;

  /// `grossTotal - itemDiscountTotal - invoiceDiscount`. What the party owes.
  final int netTotalCents;

  /// Cost of the goods sold, snapshotted at posting time for gross profit
  /// reporting that does not drift when costs change.
  final int costTotalCents;
  final String? discountReason;

  /// Set when a discount beyond the configured ceiling was authorised.
  final int? discountApprovedByUserId;
  final String? notes;
  final int createdByUserId;
  final DateTime createdAt;
  final DateTime? postedAt;
  final int? postedByUserId;
  final DateTime? cancelledAt;
  final int? cancelledByUserId;
  final String? cancelReason;
  const Invoice({
    required this.id,
    required this.invoiceNumber,
    required this.kind,
    required this.status,
    required this.invoiceDate,
    this.dueDate,
    required this.partyType,
    this.agentId,
    this.shopId,
    this.customerName,
    this.customerPhone,
    this.stockTransactionId,
    required this.grossTotalCents,
    required this.itemDiscountTotalCents,
    required this.invoiceDiscountType,
    required this.invoiceDiscountValue,
    required this.invoiceDiscountCents,
    required this.netTotalCents,
    required this.costTotalCents,
    this.discountReason,
    this.discountApprovedByUserId,
    this.notes,
    required this.createdByUserId,
    required this.createdAt,
    this.postedAt,
    this.postedByUserId,
    this.cancelledAt,
    this.cancelledByUserId,
    this.cancelReason,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['invoice_number'] = Variable<String>(invoiceNumber);
    {
      map['kind'] = Variable<String>($InvoicesTable.$converterkind.toSql(kind));
    }
    {
      map['status'] = Variable<String>(
        $InvoicesTable.$converterstatus.toSql(status),
      );
    }
    map['invoice_date'] = Variable<DateTime>(invoiceDate);
    if (!nullToAbsent || dueDate != null) {
      map['due_date'] = Variable<DateTime>(dueDate);
    }
    {
      map['party_type'] = Variable<String>(
        $InvoicesTable.$converterpartyType.toSql(partyType),
      );
    }
    if (!nullToAbsent || agentId != null) {
      map['agent_id'] = Variable<int>(agentId);
    }
    if (!nullToAbsent || shopId != null) {
      map['shop_id'] = Variable<int>(shopId);
    }
    if (!nullToAbsent || customerName != null) {
      map['customer_name'] = Variable<String>(customerName);
    }
    if (!nullToAbsent || customerPhone != null) {
      map['customer_phone'] = Variable<String>(customerPhone);
    }
    if (!nullToAbsent || stockTransactionId != null) {
      map['stock_transaction_id'] = Variable<int>(stockTransactionId);
    }
    map['gross_total_cents'] = Variable<int>(grossTotalCents);
    map['item_discount_total_cents'] = Variable<int>(itemDiscountTotalCents);
    {
      map['invoice_discount_type'] = Variable<String>(
        $InvoicesTable.$converterinvoiceDiscountType.toSql(invoiceDiscountType),
      );
    }
    map['invoice_discount_value'] = Variable<int>(invoiceDiscountValue);
    map['invoice_discount_cents'] = Variable<int>(invoiceDiscountCents);
    map['net_total_cents'] = Variable<int>(netTotalCents);
    map['cost_total_cents'] = Variable<int>(costTotalCents);
    if (!nullToAbsent || discountReason != null) {
      map['discount_reason'] = Variable<String>(discountReason);
    }
    if (!nullToAbsent || discountApprovedByUserId != null) {
      map['discount_approved_by_user_id'] = Variable<int>(
        discountApprovedByUserId,
      );
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_by_user_id'] = Variable<int>(createdByUserId);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || postedAt != null) {
      map['posted_at'] = Variable<DateTime>(postedAt);
    }
    if (!nullToAbsent || postedByUserId != null) {
      map['posted_by_user_id'] = Variable<int>(postedByUserId);
    }
    if (!nullToAbsent || cancelledAt != null) {
      map['cancelled_at'] = Variable<DateTime>(cancelledAt);
    }
    if (!nullToAbsent || cancelledByUserId != null) {
      map['cancelled_by_user_id'] = Variable<int>(cancelledByUserId);
    }
    if (!nullToAbsent || cancelReason != null) {
      map['cancel_reason'] = Variable<String>(cancelReason);
    }
    return map;
  }

