class InvoiceItem extends DataClass implements Insertable<InvoiceItem> {
  final int id;
  final int invoiceId;
  final int lineNumber;
  final int productId;

  /// Snapshots of the product as it was when billed.
  final String productNameSnapshot;
  final String skuSnapshot;
  final int quantity;

  /// Price actually charged per base unit, preserved for the life of the row.
  final int unitPriceCents;

  /// `quantity * unitPriceCents`.
  final int grossCents;
  final DiscountType discountType;

  /// Basis points when the type is percentage, cents when fixed amount. The
  /// original input is kept alongside the resolved amount so a printed invoice
  /// can still show "10%" years later.
  final int discountValue;
  final int discountCents;

  /// `grossCents - discountCents`.
  final int netCents;

  /// Unit cost at the time of sale, for gross profit by product.
  final int unitCostSnapshotCents;

  /// Quantity already returned against this line, maintained by the returns
  /// module so a line cannot be over-returned.
  final int returnedQuantity;
  final String? notes;
  const InvoiceItem({
    required this.id,
    required this.invoiceId,
    required this.lineNumber,
    required this.productId,
    required this.productNameSnapshot,
    required this.skuSnapshot,
    required this.quantity,
    required this.unitPriceCents,
    required this.grossCents,
    required this.discountType,
    required this.discountValue,
    required this.discountCents,
    required this.netCents,
    required this.unitCostSnapshotCents,
    required this.returnedQuantity,
    this.notes,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['invoice_id'] = Variable<int>(invoiceId);
    map['line_number'] = Variable<int>(lineNumber);
    map['product_id'] = Variable<int>(productId);
    map['product_name_snapshot'] = Variable<String>(productNameSnapshot);
    map['sku_snapshot'] = Variable<String>(skuSnapshot);
    map['quantity'] = Variable<int>(quantity);
    map['unit_price_cents'] = Variable<int>(unitPriceCents);
    map['gross_cents'] = Variable<int>(grossCents);
    {
      map['discount_type'] = Variable<String>(
        $InvoiceItemsTable.$converterdiscountType.toSql(discountType),
      );
    }
    map['discount_value'] = Variable<int>(discountValue);
    map['discount_cents'] = Variable<int>(discountCents);
    map['net_cents'] = Variable<int>(netCents);
    map['unit_cost_snapshot_cents'] = Variable<int>(unitCostSnapshotCents);
    map['returned_quantity'] = Variable<int>(returnedQuantity);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    return map;
  }

  InvoiceItemsCompanion toCompanion(bool nullToAbsent) {
    return InvoiceItemsCompanion(
      id: Value(id),
      invoiceId: Value(invoiceId),
      lineNumber: Value(lineNumber),
      productId: Value(productId),
      productNameSnapshot: Value(productNameSnapshot),
      skuSnapshot: Value(skuSnapshot),
      quantity: Value(quantity),
      unitPriceCents: Value(unitPriceCents),
      grossCents: Value(grossCents),
      discountType: Value(discountType),
      discountValue: Value(discountValue),
      discountCents: Value(discountCents),
      netCents: Value(netCents),
      unitCostSnapshotCents: Value(unitCostSnapshotCents),
      returnedQuantity: Value(returnedQuantity),
      notes: notes == null && nullToAbsent
          ? const Value.absent()
          : Value(notes),
    );
  }

  factory InvoiceItem.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return InvoiceItem(
      id: serializer.fromJson<int>(json['id']),
      invoiceId: serializer.fromJson<int>(json['invoiceId']),
      lineNumber: serializer.fromJson<int>(json['lineNumber']),
      productId: serializer.fromJson<int>(json['productId']),
      productNameSnapshot: serializer.fromJson<String>(
        json['productNameSnapshot'],
      ),
      skuSnapshot: serializer.fromJson<String>(json['skuSnapshot']),
