      discountCents: serializer.fromJson<int>(json['discountCents']),
      netCents: serializer.fromJson<int>(json['netCents']),
      unitCostSnapshotCents: serializer.fromJson<int>(
        json['unitCostSnapshotCents'],
      ),
      returnedQuantity: serializer.fromJson<int>(json['returnedQuantity']),
      notes: serializer.fromJson<String?>(json['notes']),
    );
  }
  @override
