    if (baseAmountCents.present) {
      map['base_amount_cents'] = Variable<int>(baseAmountCents.value);
    }
    if (reason.present) {
      map['reason'] = Variable<String>(reason.value);
    }
    if (exceededLimit.present) {
      map['exceeded_limit'] = Variable<bool>(exceededLimit.value);
    }
    if (grantedByUserId.present) {
      map['granted_by_user_id'] = Variable<int>(grantedByUserId.value);
    }
    if (approvedByUserId.present) {
      map['approved_by_user_id'] = Variable<int>(approvedByUserId.value);
    }
    if (grantedAt.present) {
      map['granted_at'] = Variable<DateTime>(grantedAt.value);
    }
    return map;
  }

  @override
  String toString() {
    return (StringBuffer('DiscountRecordsCompanion(')
          ..write('id: $id, ')
          ..write('scope: $scope, ')
          ..write('invoiceId: $invoiceId, ')
          ..write('invoiceItemId: $invoiceItemId, ')
          ..write('productId: $productId, ')
          ..write('discountType: $discountType, ')
          ..write('discountValue: $discountValue, ')
          ..write('discountCents: $discountCents, ')
          ..write('baseAmountCents: $baseAmountCents, ')
          ..write('reason: $reason, ')
          ..write('exceededLimit: $exceededLimit, ')
          ..write('grantedByUserId: $grantedByUserId, ')
          ..write('approvedByUserId: $approvedByUserId, ')
          ..write('grantedAt: $grantedAt')
          ..write(')'))
        .toString();
  }
}

