class Payment extends DataClass implements Insertable<Payment> {
  final int id;
  final String receiptNumber;
  final PaymentDirection direction;
  final PaymentMethod method;

  /// Cash, bank transfer and card payments are created already cleared.
  /// Cheques start pending.
  final PaymentStatus status;
  final DateTime paymentDate;
  final PartyType partyType;
  final int? agentId;
  final int? shopId;
  final int? employeeId;
  final String? payerName;

  /// Gross amount of the instrument, always positive.
  final int amountCents;

  /// Cache of the sum of this payment's allocations, maintained in the same
  /// transaction as the allocations themselves. The difference against
  /// [amountCents] is the unallocated advance.
  final int allocatedCents;
  final String? bankName;
  final String? referenceNumber;
  final String? notes;
  final int createdByUserId;
  final DateTime createdAt;
  final DateTime? clearedAt;
  final DateTime? bouncedAt;
  final DateTime? cancelledAt;
  final int? cancelledByUserId;
  final String? cancelReason;
  const Payment({
    required this.id,
    required this.receiptNumber,
    required this.direction,
    required this.method,
    required this.status,
    required this.paymentDate,
    required this.partyType,
    this.agentId,
    this.shopId,
    this.employeeId,
    this.payerName,
    required this.amountCents,
    required this.allocatedCents,
    this.bankName,
    this.referenceNumber,
    this.notes,
    required this.createdByUserId,
    required this.createdAt,
    this.clearedAt,
    this.bouncedAt,
    this.cancelledAt,
    this.cancelledByUserId,
    this.cancelReason,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['receipt_number'] = Variable<String>(receiptNumber);
    {
      map['direction'] = Variable<String>(
        $PaymentsTable.$converterdirection.toSql(direction),
      );
    }
    {
      map['method'] = Variable<String>(
        $PaymentsTable.$convertermethod.toSql(method),
      );
    }
    {
      map['status'] = Variable<String>(
        $PaymentsTable.$converterstatus.toSql(status),
      );
    }
    map['payment_date'] = Variable<DateTime>(paymentDate);
    {
      map['party_type'] = Variable<String>(
        $PaymentsTable.$converterpartyType.toSql(partyType),
      );
    }
    if (!nullToAbsent || agentId != null) {
      map['agent_id'] = Variable<int>(agentId);
    }
    if (!nullToAbsent || shopId != null) {
      map['shop_id'] = Variable<int>(shopId);
    }
    if (!nullToAbsent || employeeId != null) {
      map['employee_id'] = Variable<int>(employeeId);
    }
    if (!nullToAbsent || payerName != null) {
      map['payer_name'] = Variable<String>(payerName);
    }
    map['amount_cents'] = Variable<int>(amountCents);
    map['allocated_cents'] = Variable<int>(allocatedCents);
    if (!nullToAbsent || bankName != null) {
      map['bank_name'] = Variable<String>(bankName);
    }
    if (!nullToAbsent || referenceNumber != null) {
      map['reference_number'] = Variable<String>(referenceNumber);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_by_user_id'] = Variable<int>(createdByUserId);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || clearedAt != null) {
      map['cleared_at'] = Variable<DateTime>(clearedAt);
    }
    if (!nullToAbsent || bouncedAt != null) {
      map['bounced_at'] = Variable<DateTime>(bouncedAt);
    }
    if (!nullToAbsent || cancelledAt != null) {
      map['cancelled_at'] = Variable<DateTime>(cancelledAt);
    }
    if (!nullToAbsent || cancelledByUserId != null) {
      map['cancelled_by_user_id'] = Variable<int>(cancelledByUserId);
    }
    if (!nullToAbsent || cancelReason != null) {
      map['cancel_reason'] = Variable<String>(cancelReason);
    }
    return map;
  }

  PaymentsCompanion toCompanion(bool nullToAbsent) {
    return PaymentsCompanion(
      id: Value(id),
      receiptNumber: Value(receiptNumber),
      direction: Value(direction),
      method: Value(method),
      status: Value(status),
      paymentDate: Value(paymentDate),
      partyType: Value(partyType),
      agentId: agentId == null && nullToAbsent
          ? const Value.absent()
          : Value(agentId),
