class ChequeReminder extends DataClass implements Insertable<ChequeReminder> {
  final int id;
  final int chequeId;

  /// The number it was sent to, in international form without the plus.
  final String recipient;
  final DateTime attemptedAt;
  final bool delivered;
  final String? error;
  const ChequeReminder({
    required this.id,
    required this.chequeId,
    required this.recipient,
    required this.attemptedAt,
    required this.delivered,
    this.error,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['cheque_id'] = Variable<int>(chequeId);
    map['recipient'] = Variable<String>(recipient);
    map['attempted_at'] = Variable<DateTime>(attemptedAt);
    map['delivered'] = Variable<bool>(delivered);
    if (!nullToAbsent || error != null) {
      map['error'] = Variable<String>(error);
    }
    return map;
  }

  ChequeRemindersCompanion toCompanion(bool nullToAbsent) {
    return ChequeRemindersCompanion(
      id: Value(id),
      chequeId: Value(chequeId),
      recipient: Value(recipient),
      attemptedAt: Value(attemptedAt),
      delivered: Value(delivered),
      error: error == null && nullToAbsent
          ? const Value.absent()
          : Value(error),
    );
  }

  factory ChequeReminder.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return ChequeReminder(
      id: serializer.fromJson<int>(json['id']),
      chequeId: serializer.fromJson<int>(json['chequeId']),
      recipient: serializer.fromJson<String>(json['recipient']),
      attemptedAt: serializer.fromJson<DateTime>(json['attemptedAt']),
      delivered: serializer.fromJson<bool>(json['delivered']),
      error: serializer.fromJson<String?>(json['error']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'chequeId': serializer.toJson<int>(chequeId),
      'recipient': serializer.toJson<String>(recipient),
      'attemptedAt': serializer.toJson<DateTime>(attemptedAt),
      'delivered': serializer.toJson<bool>(delivered),
      'error': serializer.toJson<String?>(error),
    };
  }

  ChequeReminder copyWith({
    int? id,
    int? chequeId,
    String? recipient,
    DateTime? attemptedAt,
    bool? delivered,
    Value<String?> error = const Value.absent(),
  }) => ChequeReminder(
    id: id ?? this.id,
    chequeId: chequeId ?? this.chequeId,
    recipient: recipient ?? this.recipient,
    attemptedAt: attemptedAt ?? this.attemptedAt,
    delivered: delivered ?? this.delivered,
    error: error.present ? error.value : this.error,
  );
  ChequeReminder copyWithCompanion(ChequeRemindersCompanion data) {
    return ChequeReminder(
      id: data.id.present ? data.id.value : this.id,
      chequeId: data.chequeId.present ? data.chequeId.value : this.chequeId,
      recipient: data.recipient.present ? data.recipient.value : this.recipient,
      attemptedAt: data.attemptedAt.present
          ? data.attemptedAt.value
          : this.attemptedAt,
      delivered: data.delivered.present ? data.delivered.value : this.delivered,
      error: data.error.present ? data.error.value : this.error,
    );
  }

  @override
