    return (StringBuffer('ChequeReminder(')
          ..write('id: $id, ')
          ..write('chequeId: $chequeId, ')
          ..write('recipient: $recipient, ')
          ..write('attemptedAt: $attemptedAt, ')
          ..write('delivered: $delivered, ')
          ..write('error: $error')
          ..write(')'))
        .toString();
  }

