class ReturnDocument extends DataClass implements Insertable<ReturnDocument> {
  final int id;
  final String returnNumber;
  final ReturnRoute route;
  final ReturnStatus status;
  final DateTime returnDate;

  /// The invoice being returned against, when the goods can be traced to one.
  final int? originInvoiceId;

  /// The transfer or supply document the goods originally came on.
  final int? originStockTransactionId;
  final int fromLocationId;

  /// Where accepted goods will land. Rejected quantities always go to the
  /// damaged location instead, regardless of this value.
  final int toLocationId;
  final int? agentId;
  final int? shopId;
  final ReturnReason reason;
  final String? reasonNote;

  /// Required for [ReturnRoute.shopToWarehouse], which bypasses the agent.
  final int? authorisedByUserId;

  /// The movement that took the goods out of the returning location.
  final int? receiptTransactionId;

  /// The movement that placed inspected goods into stock or quarantine.
  final int? dispositionTransactionId;
  final int totalQuantity;

  /// Value of the returned goods at the prices they were originally billed.
  final int totalValueCents;
  final String? notes;
  final int createdByUserId;
  final DateTime createdAt;
  final DateTime? postedAt;
  final DateTime? completedAt;
  final DateTime? cancelledAt;
  final String? cancelReason;
  const ReturnDocument({
    required this.id,
    required this.returnNumber,
    required this.route,
    required this.status,
    required this.returnDate,
    this.originInvoiceId,
    this.originStockTransactionId,
    required this.fromLocationId,
    required this.toLocationId,
    this.agentId,
    this.shopId,
    required this.reason,
    this.reasonNote,
    this.authorisedByUserId,
    this.receiptTransactionId,
    this.dispositionTransactionId,
    required this.totalQuantity,
    required this.totalValueCents,
    this.notes,
    required this.createdByUserId,
    required this.createdAt,
    this.postedAt,
    this.completedAt,
    this.cancelledAt,
    this.cancelReason,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['return_number'] = Variable<String>(returnNumber);
    {
      map['route'] = Variable<String>(
        $ReturnDocumentsTable.$converterroute.toSql(route),
      );
    }
    {
      map['status'] = Variable<String>(
        $ReturnDocumentsTable.$converterstatus.toSql(status),
      );
    }
    map['return_date'] = Variable<DateTime>(returnDate);
    if (!nullToAbsent || originInvoiceId != null) {
      map['origin_invoice_id'] = Variable<int>(originInvoiceId);
    }
    if (!nullToAbsent || originStockTransactionId != null) {
      map['origin_stock_transaction_id'] = Variable<int>(
        originStockTransactionId,
      );
    }
    map['from_location_id'] = Variable<int>(fromLocationId);
    map['to_location_id'] = Variable<int>(toLocationId);
    if (!nullToAbsent || agentId != null) {
      map['agent_id'] = Variable<int>(agentId);
    }
    if (!nullToAbsent || shopId != null) {
      map['shop_id'] = Variable<int>(shopId);
    }
    {
      map['reason'] = Variable<String>(
        $ReturnDocumentsTable.$converterreason.toSql(reason),
      );
    }
    if (!nullToAbsent || reasonNote != null) {
      map['reason_note'] = Variable<String>(reasonNote);
    }
    if (!nullToAbsent || authorisedByUserId != null) {
      map['authorised_by_user_id'] = Variable<int>(authorisedByUserId);
    }
    if (!nullToAbsent || receiptTransactionId != null) {
      map['receipt_transaction_id'] = Variable<int>(receiptTransactionId);
    }
    if (!nullToAbsent || dispositionTransactionId != null) {
      map['disposition_transaction_id'] = Variable<int>(
        dispositionTransactionId,
      );
    }
    map['total_quantity'] = Variable<int>(totalQuantity);
    map['total_value_cents'] = Variable<int>(totalValueCents);
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_by_user_id'] = Variable<int>(createdByUserId);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || postedAt != null) {
      map['posted_at'] = Variable<DateTime>(postedAt);
    }
    if (!nullToAbsent || completedAt != null) {
      map['completed_at'] = Variable<DateTime>(completedAt);
    }
    if (!nullToAbsent || cancelledAt != null) {
      map['cancelled_at'] = Variable<DateTime>(cancelledAt);
    }
    if (!nullToAbsent || cancelReason != null) {
      map['cancel_reason'] = Variable<String>(cancelReason);
    }
    return map;
  }

