class CreditNote extends DataClass implements Insertable<CreditNote> {
  final int id;
  final String creditNoteNumber;
  final InvoiceStatus status;
  final DateTime issueDate;

  /// The return that justifies this credit, when there is one.
  final int? returnId;

  /// The invoice the credit relates to. Application to invoices is recorded
  /// separately so a credit can be spread across several of them.
  final int? originInvoiceId;
  final PartyType partyType;
  final int? agentId;
  final int? shopId;
  final int amountCents;

  /// Cache of the sum of applications; the remainder is available credit.
  final int appliedCents;
  final String? reason;
  final String? notes;
  final int createdByUserId;
  final DateTime createdAt;
  final DateTime? postedAt;
  final DateTime? cancelledAt;
  final String? cancelReason;
  const CreditNote({
    required this.id,
    required this.creditNoteNumber,
    required this.status,
    required this.issueDate,
    this.returnId,
    this.originInvoiceId,
    required this.partyType,
    this.agentId,
    this.shopId,
    required this.amountCents,
    required this.appliedCents,
    this.reason,
    this.notes,
    required this.createdByUserId,
    required this.createdAt,
    this.postedAt,
    this.cancelledAt,
    this.cancelReason,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['credit_note_number'] = Variable<String>(creditNoteNumber);
    {
      map['status'] = Variable<String>(
        $CreditNotesTable.$converterstatus.toSql(status),
      );
    }
    map['issue_date'] = Variable<DateTime>(issueDate);
    if (!nullToAbsent || returnId != null) {
      map['return_id'] = Variable<int>(returnId);
    }
    if (!nullToAbsent || originInvoiceId != null) {
      map['origin_invoice_id'] = Variable<int>(originInvoiceId);
    }
    {
      map['party_type'] = Variable<String>(
        $CreditNotesTable.$converterpartyType.toSql(partyType),
      );
    }
    if (!nullToAbsent || agentId != null) {
      map['agent_id'] = Variable<int>(agentId);
    }
    if (!nullToAbsent || shopId != null) {
      map['shop_id'] = Variable<int>(shopId);
    }
    map['amount_cents'] = Variable<int>(amountCents);
    map['applied_cents'] = Variable<int>(appliedCents);
    if (!nullToAbsent || reason != null) {
      map['reason'] = Variable<String>(reason);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['created_by_user_id'] = Variable<int>(createdByUserId);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || postedAt != null) {
      map['posted_at'] = Variable<DateTime>(postedAt);
    }
    if (!nullToAbsent || cancelledAt != null) {
      map['cancelled_at'] = Variable<DateTime>(cancelledAt);
    }
    if (!nullToAbsent || cancelReason != null) {
      map['cancel_reason'] = Variable<String>(cancelReason);
    }
    return map;
  }

  CreditNotesCompanion toCompanion(bool nullToAbsent) {
    return CreditNotesCompanion(
      id: Value(id),
      creditNoteNumber: Value(creditNoteNumber),
      status: Value(status),
      issueDate: Value(issueDate),
      returnId: returnId == null && nullToAbsent
          ? const Value.absent()
          : Value(returnId),
      originInvoiceId: originInvoiceId == null && nullToAbsent
          ? const Value.absent()
          : Value(originInvoiceId),
      partyType: Value(partyType),
      agentId: agentId == null && nullToAbsent
          ? const Value.absent()
          : Value(agentId),
      shopId: shopId == null && nullToAbsent
          ? const Value.absent()
          : Value(shopId),
      amountCents: Value(amountCents),
      appliedCents: Value(appliedCents),
      reason: reason == null && nullToAbsent
