class Salary extends DataClass implements Insertable<Salary> {
  final int id;
  final String voucherNumber;
  final int employeeId;
  final int periodYear;
  final int periodMonth;
  final int basicSalaryCents;
  final int allowancesCents;
  final int bonusCents;
  final int deductionsCents;

  /// Portion of outstanding advances recovered in this period.
  final int advanceDeductedCents;

  /// `basic + allowances + bonus - deductions - advanceDeducted`.
  final int netSalaryCents;

  /// Cache of the sum of [SalaryPayments] for this salary.
  final int paidCents;
  final SalaryStatus status;
  final String? notes;
  final int? approvedByUserId;
  final int createdByUserId;
  final DateTime createdAt;
  final DateTime? approvedAt;
  final DateTime? cancelledAt;
