    map['period_year'] = Variable<int>(periodYear);
    map['period_month'] = Variable<int>(periodMonth);
    map['basic_salary_cents'] = Variable<int>(basicSalaryCents);
    map['allowances_cents'] = Variable<int>(allowancesCents);
    map['bonus_cents'] = Variable<int>(bonusCents);
    map['deductions_cents'] = Variable<int>(deductionsCents);
    map['advance_deducted_cents'] = Variable<int>(advanceDeductedCents);
    map['net_salary_cents'] = Variable<int>(netSalaryCents);
    map['paid_cents'] = Variable<int>(paidCents);
    {
      map['status'] = Variable<String>(
        $SalariesTable.$converterstatus.toSql(status),
      );
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    if (!nullToAbsent || approvedByUserId != null) {
      map['approved_by_user_id'] = Variable<int>(approvedByUserId);
    }
    map['created_by_user_id'] = Variable<int>(createdByUserId);
    map['created_at'] = Variable<DateTime>(createdAt);
    if (!nullToAbsent || approvedAt != null) {
      map['approved_at'] = Variable<DateTime>(approvedAt);
    }
    if (!nullToAbsent || cancelledAt != null) {
      map['cancelled_at'] = Variable<DateTime>(cancelledAt);
    }
    return map;
  }

